        {
          "section_id": "contained",
          "intent": "Stepwise 5-note ostinato in D minor with rests every other bar to create space",
          "density": "sparse"
        },
        {
          "section_id": "pressure",
          "intent": "Shift ostinato up a third and shorten rests, adding rhythmic displacement on last eighth",
          "density": "medium"
