          "section_id": "contained",
          "intent": "Single soft strokes on off-beats, sparse and dry",
          "density": "sparse"
        },
        {
          "section_id": "pressure",
          "intent": "Add cross-rhythm accent on beat 4 and intermittent sixteenth pickup to mark urgency",
          "density": "medium"
